import { assetUrl } from "./assets";
import { specLibrary } from "./spec-library";
import { defaultBlockSpacing, defaultGrid } from "../core/grid";
import { newIso, type CatalogItem, type IsoDocument, type PipeSpec } from "../core/model";

/** Built-in specifications served from library/ (generated by scripts/build-piping-library.py). */
export interface LibrarySpecSummary {
  slug: string;
  id: string;
  name: string;
  material: string;
  service: string;
  rating: string;
  rowCount: number;
}

let index: Promise<LibrarySpecSummary[]> | null = null;
export function loadSpecIndex(): Promise<LibrarySpecSummary[]> {
  index ??= fetch(assetUrl("library/index.json"))
    .then((r) => {
      if (!r.ok) throw new Error("The specification library could not load.");
      return r.json() as Promise<LibrarySpecSummary[]>;
    })
    .catch((e) => {
      index = null;
      throw e;
    });
  return index;
}

/**
 * Load a library specification ready to embed in a drawing. Catalogue ids are unique across every
 * specification in a document, so they are namespaced by the (possibly renamed) specification id.
 */
export async function loadLibrarySpec(slug: string, doc?: IsoDocument): Promise<PipeSpec> {
  const response = await fetch(assetUrl("library/specs/" + encodeURIComponent(slug) + ".json"));
  if (!response.ok) throw new Error("The specification could not load.");
  // The branch table's legend (branchCodes) is kept: it names the connection each chart code stands for.
  const raw = (await response.json()) as PipeSpec & { unsizedItems?: unknown };
  delete raw.unsizedItems;
  return namespaceSpec(raw, uniqueSpecId(raw.id, doc));
}

export function uniqueSpecId(base: string, doc?: IsoDocument): string {
  const taken = new Set(doc?.specs.map((s) => s.id) ?? []);
  let id = base,
    n = 2;
  while (taken.has(id)) id = base + "-" + n++;
  return id;
}

export function namespaceSpec(spec: PipeSpec, id: string): PipeSpec {
  const strip = (key: string) => key.replace(/^[^:/]*[:/]/, "");
  return {
    ...spec,
    id,
    fittings: spec.fittings.map((f: CatalogItem) => ({ ...f, id: id + ":" + strip(f.id) })),
  };
}

/** A specification from the drafter's own library, ready to embed in a drawing (see spec-library.ts). */
export async function loadSavedSpec(id: string, doc?: IsoDocument): Promise<PipeSpec> {
  const saved = await specLibrary().get(id);
  if (!saved) throw new Error(`Specification ${id} is no longer in your library.`);
  return namespaceSpec(saved, uniqueSpecId(saved.id, doc));
}
/**
 * The specification a new drawing starts on for a standard library slug: the drafter's own refined copy of it (the
 * same id in their library) when they have one, else the standard library's.
 */
export async function startingSpec(slug: string): Promise<PipeSpec> {
  const id = (await loadSpecIndex().catch(() => [] as LibrarySpecSummary[])).find((s) => s.slug === slug)?.id ?? slug;
  const own = await specLibrary().get(id).catch(() => undefined);
  return own ? namespaceSpec(own, own.id) : loadLibrarySpec(slug);
}

/**
 * A new drawing starts on the standard library's general-service spec A, falling back to the built-in spec offline,
 * in feet and inches on tabloid paper: one cell of the isometric paper routes one foot of pipe.
 */
export async function newIsoWithDefaultSpec(units: IsoDocument["units"] = "imperial"): Promise<IsoDocument> {
  const doc = newIso();
  doc.units = units;
  doc.paper = "tabloid";
  doc.grid = { ...defaultGrid(), spacing: defaultBlockSpacing(units) };
  try {
    doc.specs = [await startingSpec("a")];
  } catch {
    // Keep the bundled Schedule 40 specification.
  }
  return doc;
}

/** Most routing starts at 2″; small-bore-first specifications should not default to ⅛″. */
export const defaultNps = (spec: PipeSpec) =>
  spec.sizes.find((s) => s.nps === 2)?.nps ?? spec.sizes[0]?.nps ?? 2;

/** Common nominal sizes, offered for a specification that lists none and no pipe of the drawing's to go by. */
export const COMMON_NPS = [0.5, 0.75, 1, 1.5, 2, 3, 4, 6, 8, 10, 12];
/**
 * The sizes a pipe can be routed at in a specification: the sizes it lists. One that lists none (a specification
 * read from a PCF, which carries no size table) offers the sizes its pipes are drawn at, else those of the drawing's
 * pipes, else the common sizes; `listed` says which, so the editor can explain the sizes are not the specification's.
 */
export function routingSizes(doc: Pick<IsoDocument, "runs">, spec: PipeSpec | undefined): { sizes: number[]; listed: boolean } {
  if (!spec) return { sizes: [], listed: false };
  if (spec.sizes.length) return { sizes: spec.sizes.map((s) => s.nps), listed: true };
  const used = (runs: Array<{ nps: number }>) => [...new Set(runs.map((r) => r.nps))].sort((a, b) => a - b);
  const own = used(doc.runs.filter((r) => r.specId === spec.id)), any = used(doc.runs);
  return { sizes: own.length ? own : any.length ? any : COMMON_NPS, listed: false };
}

export interface DrawingTemplate {
  id: string;
  name: string;
  detail: string;
  spec: string;
  paper: NonNullable<IsoDocument["paper"]>;
  units: IsoDocument["units"];
}
/** Starting points offered by New: sheet size, units and specification. */
export const TEMPLATES: DrawingTemplate[] = [
  { id: "imperial-tabloid", name: "Imperial · Tabloid", detail: "11×17 sheet · feet & inches · Spec A carbon steel", spec: "a", paper: "tabloid", units: "imperial" },
  { id: "imperial-letter", name: "Imperial · Letter", detail: "8½×11 sheet · feet & inches · Spec A carbon steel", spec: "a", paper: "letter", units: "imperial" },
  { id: "stainless-tabloid", name: "Stainless · Tabloid", detail: "11×17 sheet · feet & inches · Spec SS-A stainless", spec: "ss-a", paper: "tabloid", units: "imperial" },
  { id: "metric-tabloid", name: "Metric · Tabloid", detail: "11×17 sheet · millimetres · Spec A carbon steel", spec: "a", paper: "tabloid", units: "mm" },
  { id: "metric-a3", name: "Metric · A3", detail: "A3 sheet · millimetres · Spec A carbon steel", spec: "a", paper: "a3", units: "mm" },
];

export async function newIsoFromTemplate(template: DrawingTemplate, title = "Piping isometric"): Promise<IsoDocument> {
  const doc = newIso();
  doc.title = title;
  doc.paper = template.paper;
  doc.units = template.units;
  doc.grid = { ...defaultGrid(), spacing: defaultBlockSpacing(template.units) };
  // Never substitute carbon steel for a requested stainless or pressure-class specification.
  doc.specs = [await startingSpec(template.spec)];
  return doc;
}
